$stage = Join-Path $env:TEMP "pm-trader-package"

if (Test-Path $stage) { Remove-Item $stage -Recurse -Force -ErrorAction SilentlyContinue }
if (Test-Path $out)   { Remove-Item $out -Force -ErrorAction SilentlyContinue }
New-Item -ItemType Directory -Path $stage -Force | Out-Null

# 需要打包的顶层项
$include = @(
    "backend", "frontend", "config", "docs",
    "Dockerfile", ".dockerignore", "docker-compose.yml",
    ".env.docker.example", ".env.example", "config.example.yaml",
    "README.md", "requirements.txt", "run.py", "run_minimal.py"
)

$copied = 0
foreach ($item in $include) {
    $p = Join-Path $src $item
    if (-not (Test-Path $p)) { Write-Output "MISSING: $item"; continue }
    if (Test-Path $p -PathType Container) {
        # 目录：robocopy 排除缓存
        $null = robocopy $p (Join-Path $stage $item) /E /XD __pycache__ .pytest_cache /XF *.pyc /NFL /NDL /NJH /NJS /NP
        $copied++
    } else {
        Copy-Item $p (Join-Path $stage $item) -Force
        $copied++
    }
}
Write-Output "COPIED_ITEMS=$copied"

# 打包
Compress-Archive -Path "$stage\*" -DestinationPath $out -CompressionLevel Optimal
if (Test-Path $out) {
    $size = [math]::Round((Get-Item $out).Length / 1KB, 1)
    Write-Output "PACKAGE_OK $out  ${size}KB"
    Write-Output "FILES_IN_PACKAGE=$((Get-ChildItem $stage -Recurse -File | Measure-Object).Count)"
} else {
    Write-Output "PACKAGE_FAILED"
}
Remove-Item $stage -Recurse -Force -ErrorAction SilentlyContinue
