{"content":""""把项目打包为自包含 zip（含内置 Python312）。"""
import os
import zipfile

ROOT = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(ROOT), "polymarket-trader-standalone.zip")

EXCLUDE_DIRS = {"__pycache__", ".git", ".venv", "data", ".pytest_cache", ".mypy_cache"}
EXCLUDE_FILES = {"config.yaml"}
EXCLUDE_EXT = {".pyc", ".pyo", ".log"}


def main():
    total = 0
    n = 0
    if os.path.exists(OUT):
        os.remove(OUT)
    with zipfile.ZipFile(OUT, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as z:
        for dirpath, dirnames, filenames in os.walk(ROOT):
            rel_dir = os.path.relpath(dirpath, ROOT)
            parts = set(rel_dir.replace("\\", "/").split("/"))
            if parts & EXCLUDE_DIRS:
                dirnames[:] = []
                continue
            dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
            for fn in filenames:
                if fn in EXCLUDE_FILES:
                    continue
                if os.path.splitext(fn)[1] in EXCLUDE_EXT:
                    continue
                full = os.path.join(dirpath, fn)
                arc = os.path.relpath(full, ROOT).replace("\\", "/")
                try:
                    z.write(full, arc)
                    n += 1
                    total += os.path.getsize(full)
                except Exception as e:
                    print("SKIP", arc, e)
    raw = total / 1024 / 1024
    comp = os.path.getsize(OUT) / 1024 / 1024
    print("files=%d" % n)
    print("raw=%.1f MB  zip=%.1f MB" % (raw, comp))
    print("OUT=%s" % OUT)


if __name__ == "__main__":
    main()
