{"file_path":"D:\Users\Administrator\Documents\deepseek-harness\default-workspace\polymarket-trader\_sim_e2e.py","content":""""端到端模拟：加钱包 -> 实时监测 -> 策略管道 -> 自动跟单执行。

分两部分：
A. 真实链路：添加真实钱包，等服务自己轮询到交易并自动执行。
B. 注入链路：若窗口内没有真实交易，直接向回调注入合成交易，
   验证 monitor -> pipeline -> executor 全链路确实连通。
"""
import json
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.request

BASE = "http://127.0.0.1:8767"
PY = sys.executable

# 用户提供的两个真实跟单目标
WALLETS = [
    ("0x5268527977f700f9bf9b6d5cd843859e4e70135d", "HomeRunHazard"),
    ("0xf0318c32136c2db7fec88b84869aee6a1106c80c", "BreakTheBank"),
]


def http(method, path, body=None, timeout=30):
    data = json.dumps(body).encode() if body is not None else None
    headers = {"Content-Type": "application/json"} if data else {}
    req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read().decode("utf-8", "replace")
